  "content": "{\n  \"title\": \"Carbon-Aware Adaptive Routing Protocol with Real-Time Traffic Information for CPI Networks\",\n  \"focus_papers\": [\n    \"A carbon-aware routing protocol for optimizing carbon emissions in modular construction logistics\",\n    \"Cyber-Physical Internet(CPI)-enabled logistics infrastructure integration framework in the greater bay area\",\n    \"Routing protocols for B2B e-commerce logistics in cyber-physical internet(CPI)\"\n  ],\n  \"research_problem\": {\n    \"background\": \"Current CPI routing protocols optimize for either time or cost, while carbon emission optimization is emerging but lacks integration with real-time traffic data.\",\n    \"gap\": \"Existing carbon-aware routing protocols do not adapt to changing traffic conditions in real-time, potentially leading to sub-optimal routes from an emissions perspective when traffic conditions change.\",\n    \"research_questions\": [\n      \"How can a carbon-aware routing protocol be designed to incorporate real-time traffic information?\",\n      \"What framework is needed to integrate carbon metrics and traffic data in CPI networks?\",\n      \"How does the performance of carbon-aware adaptive routing compare to static carbon-aware routing in terms of emissions reduction?\"\n    ]\n  },\n  \"proposed_approach\": {\n    \"framework\": \"Two-layer CPI framework combining:\",\n    \"components\": [\n      {\n        \"name\": \"Link Layer\",\n        \"description\": \"Manages the organization of autonomous logistics areas and their interconnections, incorporating real-time traffic data collection points.\"\n      },\n      {\n        \"name\": \"Transport Layer\",\n        \"description\": \"Handles routing decisions based on carbon metrics and real-time traffic information, implementing an adaptive routing protocol.\"\n      }\n    ],\n    \"key_innovations\": [\n      \"Integration of carbon emission factors with real-time traffic data in routing tables\",\n      \"Dynamic recalculation of optimal routes when significant traffic changes are detected\",\n      \"Multi-criteria decision making balancing carbon emissions reduction with delivery time constraints\",\n      \"Traffic prediction model to anticipate congestion and proactively adjust routes\"\n    ]\n  },\n  \"experiment_plan\": {\n    \"simulation_environment\": {\n      \"tool\": \"Custom discrete event simulation in Python\",\n      \"network_model\": \"Greater Bay Area transportation network (based on Paper 3)\",\n      \"time_period\": \"24-hour simulation with varying traffic conditions\"\n    },\n    \"scenarios\": [\n      {\n        \"name\": \"Baseline Scenario\",\n        \"description\": \"Traditional shortest path routing without carbon or traffic considerations\"\n      },\n      {\n        \"name\": \"Static Carbon-Aware\",\n        \"description\": \"Carbon-aware routing without real-time traffic updates (from Paper 2)\"\n      },\n      {\n        \"name\": \"Traffic-Adaptive\",\n        \"description\": \"Traditional routing with real-time traffic updates but no carbon awareness\"\n      },\n      {\n        \"name\": \"Proposed Carbon-Aware Adaptive\",\n        \"description\": \"Carbon-aware routing with real-time traffic integration\"\n      }\n    ],\n    \"variables\": {\n      \"independent\": [\n        \"Traffic congestion levels (low, medium, high)\",\n        \"Carbon emission factor variations (different vehicle types)\",\n        \"Order density (orders per hour)\",\n        \"Time constraints (urgent vs. regular delivery)\"\n      ],\n      \"dependent\": [\n        \"Total carbon emissions (kg CO2)\",\n        \"Average delivery time (hours)\",\n        \"Route stability (number of route changes)\",\n        \"Computational overhead (processing time)\"\n      ]\n    },\n    \"implementation_steps\": [\n      \"1. Implement network model with nodes, links, and traffic conditions\",\n      \"2. Develop carbon emission calculation module based on vehicle type, load, speed, and distance\",\n      \"3. Implement baseline routing algorithms from the literature\",\n      \"4. Develop proposed carbon-aware adaptive routing algorithm\",\n      \"5. Create traffic simulation module with various congestion patterns\",\n      \"6. Design experiments to test all scenarios under varying conditions\",\n      \"7. Collect and analyze performance metrics\"\n    ],\n    \"expected_results\": {\n      \"primary_hypothesis\": \"The proposed carbon-aware adaptive routing protocol will achieve lower total carbon emissions compared to both static carbon-aware routing and traffic-adaptive routing under variable traffic conditions.\",\n      \"anticipated_findings\": [\n        \"15-20% reduction in carbon emissions compared to baseline routing\",\n        \"5-10% improvement over static carbon-aware routing in dynamic traffic scenarios\",\n        \"Minimal increase in delivery time (less than 5%) compared to time-optimized routing\",\n        \"Higher route stability in congested conditions compared to purely traffic-adaptive approaches\"\n      ]\n    },\n    \"evaluation_metrics\": {\n      \"effectiveness\": [\n        \"Total carbon emissions reduction percentage\",\n        \"Average delivery time increase percentage\",\n        \"Carbon efficiency (emissions per ton-km)\"\n      ],\n      \"efficiency\": [\n        \"Computational time for route calculation\",\n        \"Number of routing table updates\",\n        \"Memory usage for routing tables\"\n      ],\n      \"adaptability\": [\n        \"Response time to traffic changes\",\n        \"Route stability under different traffic patterns\",\n        \"Performance degradation in extreme congestion\"\n      ]\n    },\n    \"visualization_plan\": [\n      \"Heat maps showing carbon emissions across the network under different routing strategies\",\n      \"Line graphs comparing emissions and delivery time across scenarios\",\n      \"Route visualization on map with traffic 