  "content": "#!/usr/bin/env python3\n\"\"\"\nCarbon Emission Calculation Module for Carbon-Aware Adaptive Routing\n\nThis module calculates carbon emissions for routes based on vehicle type, load,\nspeed, and distance. It integrates with the network simulator to provide\nreal-time emission calculations for routing optimization.\n\nAuthor: Coding Task Agent\nDate: 2024\n\"\"\"\n\nimport math\nfrom typing import Dict, List, Tuple, Optional, Any\nfrom dataclasses import dataclass\nfrom enum import Enum\n\n\nclass VehicleType(Enum):\n    \"\"\"Enumeration of vehicle types for emission calculation\"\"\"\n    LIGHT_TRUCK = \"light_truck\"\n    MEDIUM_TRUCK = \"medium_truck\"\n    HEAVY_TRUCK = \"heavy_truck\"\n    VAN = \"van\"\n    ELECTRIC_VAN = \"electric_van\"\n    ELECTRIC_TRUCK = \"electric_truck\"\n\n\n@dataclass\nclass VehicleInfo:\n    \"\"\"Vehicle information for emission calculations\"\"\"\n    vehicle_type: VehicleType\n    load_weight: float  # in tons\n    max_capacity: float  # in tons\n    fuel_efficiency: float  # km per liter or kWh per km for electric\n\n\n@dataclass\nclass EmissionFactor:\n    \"\"\"Emission factors for different vehicle types\"\"\"\n    co2_per_km_empty: float  # kg CO2 per km when empty\n    co2_per_km_per_ton: float  # additional kg CO2 per km per ton of load\n    speed_efficiency_curve: Dict[int, float]  # speed (km/h) -> efficiency multiplier\n\n\nclass CarbonCalculator:\n    \"\"\"Main class for calculating carbon emissions in routing\"\"\"\n    \n    def __init__(self):\n        \"\"\"Initialize carbon calculator with emission factors\"\"\"\n        self.emission_factors = self._initialize_emission_factors()\n        self.electric_grid_factor = 0.5  # kg CO2 per kWh (average grid mix)\n    \n    def _initialize_emission_factors(self) -> Dict[VehicleType, EmissionFactor]:\n        \"\"\"Initialize emission factors for different vehicle types\"\"\"\n        factors = {\n            VehicleType.LIGHT_TRUCK: EmissionFactor(\n                co2_per_km_empty=0.25,  # kg CO2/km\n                co2_per_km_per_ton=0.15,  # additional kg CO2/km per ton\n                speed_efficiency_curve={\n                    20: 1.3,   # City driving - less efficient\n                    30: 1.2,\n                    40: 1.1,\n                    50: 1.0,   # Optimal speed\n                    60: 1.0,\n                    70: 1.1,\n                    80: 1.2,\n                    90: 1.4,   # Highway speeds - less efficient\n                    100: 1.6\n                }\n            ),\n            VehicleType.MEDIUM_TRUCK: EmissionFactor(\n                co2_per_km_empty=0.45,\n                co2_per_km_per_ton=0.12,\n                speed_efficiency_curve={\n                    20: 1.4,\n                    30: 1.3,\n                    40: 1.2,\n                    50: 1.0,\n                    60: 1.0,\n                    70: 1.1,\n                    80: 1.3,\n                    90: 1.5,\n                    100: 1.7\n                }\n            ),\n            VehicleType.HEAVY_TRUCK: EmissionFactor(\n                co2_per_km_empty=0.75,\n                co2_per_km_per_ton=0.08,\n                speed_efficiency_curve={\n                    20: 1.5,\n                    30: 1.4,\n                    40: 1.2,\n                    50: 1.0,\n                    60: 1.0,\n                    70: 1.2,\n                    80: 1.4,\n                    90: 1.6,\n                    100: 1.8\n                }\n            ),\n            VehicleType.VAN: EmissionFactor(\n                co2_per_km_empty=0.18,\n                co2_per_km_per_ton=0.20,\n                speed_efficiency_curve={\n                    20: 1.2,\n                    30: 1.1,\n                    40: 1.0,\n                    50: 1.0,\n                    60: 1.0,\n                    70: 1.1,\n                    80: 1.3,\n                    90: 1.5,\n                    100: 1.7\n                }\n            ),\n            VehicleType.ELECTRIC_VAN: EmissionFactor(\n                co2_per_km_empty=0.05,  # Only from electricity generation\n                co2_per_km_per_ton=0.03,\n                speed_efficiency_curve={\n                    20: 0.9,   # Electric vehicles more efficient at low speeds\n                    30: 0.9,\n                    40: 1.0,\n                    50: 1.0,\n                    60: 1.1,\n                    70: 1.2,\n                    80: 1.4,\n                    90: 1.6,\n                    100: 1.8\n                }\n            ),\n            VehicleType.ELECTRIC_TRUCK: EmissionFactor(\n                co2_per_km_empty=0.08,\n                co2_per_km_per_ton=0.04,\n                speed_efficiency_curve={\n                    20: 0.9,\n                    30: 0.9,\n                    40: 1.0,\n                    50: 1.0,\n                    60: 1.1,\n                    70: 1.3,\n                    80: 1.5,\n                    90: 1.7,\n                    100: 1.9\n                }\n            )\n        }\n        return factors\n    \n    def get_emission_factor(self, vehicle_type: VehicleType) -> EmissionFactor:\n        \"\"\"\n        Get emission factors for a specific vehicle type\n        \n        Args:\n            vehicle_type: Type of vehicle\n            \n        Returns:\n            EmissionFactor object containing emission parameters\n        \"\"\"\n        if vehicle_type not in self.emission_factors:\n            raise ValueError(f\"Unknown vehicle type: {vehicle_type}\")\n        return self.emission_factors[vehicle_type]\n    \n    def _calculate_speed_from_travel_time(self, distance: float, travel_time: float) -> float:\n        \"\"\"\n        Calculate average speed from distance and travel time\n        \n        Args:\n            distance: Distance in kilometers\n            travel_time: Travel time in minutes\n            \n        Returns:\n            Average speed in km/h\n        \"\"\"\n        if travel_time <= 0:\n            return 50.0  # Default speed if invalid travel time\n        \n        # Convert travel time from minutes to hours\n        travel_time_hours = travel_time / 60.0\n        speed = distance / travel_time_hours\n        \n        # Clamp speed to reasonable range\n        return max(5.0, min(speed, 120.0))\n    \n    def _get_speed_efficiency_multiplier(self, speed: float, vehicle_type: VehicleType) -> float:\n        \"\"\"\n        Get speed efficiency multiplier based on vehicle speed\n        \n        Args:\n            speed: Vehicle speed in km/h\n            vehicle_type: Type of vehicle\n            \n        Returns:\n            Efficiency multiplier (1.0 = optimal, >1.0 = less efficient)\n        \"\"\"\n        emission_factor = self.get_emission_factor(vehicle_type)\n        speed_curve = emission_factor.speed_efficiency_curve\n        \n        # Find the closest speed points for interpolation\n        speeds = sorted(speed_curve.keys())\n        \n        if speed <= speeds[0]:\n            return speed_curve[speeds[0]]\n        elif speed >= speeds[-1]:\n            return speed_curve[speeds[-1]]\n        \n        # Linear interpolation between two closest speed points\n        for i in range(len(speeds) - 1):\n            if speeds[i] <= speed <= speeds[i + 1]:\n                lower_speed = speeds[i]\n                upper_speed = speeds[i + 1]\n                lower_mult = speed_curve[lower_speed]\n                upper_mult = speed_curve[upper_speed]\n                \n                # Interpolate\n                ratio = (speed - lower_speed) / (upper_speed - lower_speed)\n                return lower_mult + ratio * (upper_mult - lower_mult)\n        \n        return 1.0  # Default multiplier\n    \n    def calculate_segment_emissions(self, segment: Tuple[str, str, float, float], \n                                  vehicle_type: VehicleType, load: float, \n                                  speed: Optional[float] = None) -> float:\n        \"\"\"\n        Calculate carbon emissions for a single route segment\n        \n        Args:\n            segment: Tuple of (from_node, to_node, distance_km, travel_time_min)\n            vehicle_type: Type of vehicle\n            load: Load weight in tons\n            speed: Optional speed in km/h (calculated from segment if not provided)\n            \n        Returns:\n            Carbon emissions in kg CO2\n        \"\"\"\n        from_node, to_node, distance, travel_time = segment\n        \n        if distance <= 0:\n            return 0.0\n        \n        # Calculate speed if not provided\n        if speed is None:\n            speed = self._calculate_speed_from_travel_time(distance, travel_time)\n        \n        # Get emission factors for this vehicle type\n        emission_factor = self.get_emission_factor(vehicle_type)\n        \n        # Base emissions (empty vehicle)\n        base_emissions = emission_factor.co2_per_km_empty * distance\n        \n        # Additional emissions due to load\n        load_emissions = emission_factor.co2_per_km_per_ton * load * distance\n        \n        # Speed efficiency multiplier\n        speed_multiplier = self._get_speed_efficiency_multiplier(speed, vehicle_type)\n        \n        # Total emissions\n        total_emissions = (base_emissions + load_emissions) * speed_multiplier\n        \n        return total_emissions\n    \n    def calculate_route_emissions(self, route: List[str], vehicle_info: VehicleInfo, \n                                traffic_conditions: Dict[Tuple[str, str], Dict]) -> Dict[str, Any]:\n        \"\"\"\n        Calculate total carbon emissions for a complete route\n        \n        Args:\n            route: List of node IDs representing the route path\n            vehicle_info: Vehicle information including type and load\n            traffic_conditions: Dictionary with edge info including distance and travel time\n            \n        Returns:\n            Dictionary containing total emissions and segment breakdown\n        \"\"\"\n        if len(route) < 2:\n            return {\n                'total_emissions': 0.0,\n                'segments': [],\n                'total_distance': 0.0,\n                'total_time': 0.0,\n                'average_speed': 0.0\n            }\n        \n        segment_emissions = []\n        total_emissions = 0.0\n        total_distance = 0.0\n        total_time = 0.0\n        \n        # Calculate emissions for each segment\n        for i in range(len(route) - 1):\n            from_node = route[i]\n            to_node = route[i + 1]\n            \n            # Get segment information from traffic conditions\n            segment_key = (from_node, to_node)\n            reverse_key = (to_node, from_node)\n            \n            if segment_key in traffic_conditions:\n                segment_info = traffic_conditions[segment_key]\n            elif reverse_key in traffic_conditions:\n                segment_info = traffic_conditions[reverse_key]\n            else:\n                # Default values if segment not found\n                segment_info = {'distance': 10.0, 'travel_time': 15.0}\n            \n            distance = segment_info.get('distance', 10.0)\n            travel_time = segment_info.get('travel_time', 15.0)\n            \n            # Create segment tuple\n            segment = (from_node, to_node, distance, travel_time)\n            \n            # Calculate emissions for this segment\n            emissions = self.calculate_segment_emissions(\n                segment, vehicle_info.vehicle_type, vehicle_info.load_weight\n            )\n            \n            segment_emissions.append({\n                'from': from_node,\n                'to': to_node,\n                'distance': distance,\n                'travel_time': travel_time,\n                'emissions': emissions,\n                'speed': self._calculate_speed_from_travel_time(distance, travel_time)\n            })\n            \n            total_emissions += emissions\n            total_distance += distance\n            total_time += travel_time\n        \n        # Calculate average speed for the entire route\n        average_speed = self._calculate_speed_from_travel_time(total_distance, total_time)\n        \n        return {\n            'total_emissions': total_emissions,\n            'segments': segment_emissions,\n            'total_distance': total_distance,\n            'total_time': total_time,\n            'average_speed': average_speed,\n            'vehicle_type': vehicle_info.vehicle_type.value,\n            'load_weight': vehicle_info.load_weight\n        }\n    \n    def compare_vehicle_emissions(self, route: List[str], \n                                traffic_conditions: Dict[Tuple[str, str], Dict],\n                                load_weight: float = 2.0) -> Dict[str, float]:\n        \"\"\"\n        Compare emissions across different vehicle types for the same route\n        \n        Args:\n            route: List of node IDs representing the route path\n            traffic_conditions: Dictionary with edge info\n            load_weight: Load weight in tons\n            \n        Returns:\n            Dictionary mapping vehicle types to total emissions\n        \"\"\"\n        comparisons = {}\n        \n        for vehicle_type in VehicleType:\n            vehicle_info = VehicleInfo(\n                vehicle_type=vehicle_type,\n                load_weight=load_weight,\n                max_capacity=10.0,  # Default capacity\n                fuel_efficiency=8.0  # Default efficiency\n            )\n            \n            result = self.calculate_route_emissions(route, vehicle_info, traffic_conditions)\n            comparisons[vehicle_type.value] = result['total_emissions']\n        \n        return comparisons\n\n\ndef main():\n    \"\"\"Test the carbon calculator functionality\"\"\"\n    print(\"=== Carbon Calculator Module Test ===\