  "content": "#!/usr/bin/env python3\n\"\"\"\nNetwork and Traffic Simulation Module for Carbon-Aware Adaptive Routing\n\nThis module provides network infrastructure modeling and dynamic traffic simulation\ncapabilities for logistics and transportation routing optimization.\n\nAuthor: Coding Task Agent\nDate: 2024\n\"\"\"\n\nimport networkx as nx\nimport numpy as np\nimport random\nimport math\nfrom typing import Dict, List, Tuple, Optional, Any\nfrom dataclasses import dataclass\nfrom datetime import datetime, timedelta\n\n\n@dataclass\nclass Node:\n    \"\"\"Represents a node in the transportation network\"\"\"\n    id: str\n    name: str\n    latitude: float\n    longitude: float\n    node_type: str = \"warehouse\"  # warehouse, distribution_center, customer\n\n\n@dataclass\nclass Link:\n    \"\"\"Represents a link (road segment) between two nodes\"\"\"\n    from_node: str\n    to_node: str\n    distance: float  # in kilometers\n    base_travel_time: float  # in minutes under normal conditions\n    capacity: int = 1000  # vehicles per hour\n    road_type: str = \"highway\"  # highway, arterial, local\n\n\nclass TrafficPattern:\n    \"\"\"Manages traffic patterns and congestion levels throughout the day\"\"\"\n    \n    def __init__(self):\n        # Define traffic multipliers for each hour (0-23)\n        # Values > 1 indicate higher congestion, < 1 indicate lighter traffic\n        self.hourly_multipliers = {\n            0: 0.3,   # Midnight - very light\n            1: 0.2,   # 1 AM - lightest\n            2: 0.2,   # 2 AM - lightest\n            3: 0.3,   # 3 AM - very light\n            4: 0.4,   # 4 AM - light\n            5: 0.6,   # 5 AM - building up\n            6: 0.9,   # 6 AM - morning buildup\n            7: 1.4,   # 7 AM - morning rush\n            8: 1.8,   # 8 AM - peak morning rush\n            9: 1.3,   # 9 AM - post-rush\n            10: 1.0,  # 10 AM - normal\n            11: 1.1,  # 11 AM - normal+\n            12: 1.2,  # Noon - lunch traffic\n            13: 1.1,  # 1 PM - post-lunch\n            14: 1.0,  # 2 PM - normal\n            15: 1.1,  # 3 PM - afternoon buildup\n            16: 1.3,  # 4 PM - afternoon buildup\n            17: 1.6,  # 5 PM - evening rush\n            18: 1.8,  # 6 PM - peak evening rush\n            19: 1.4,  # 7 PM - evening rush\n            20: 1.0,  # 8 PM - settling down\n            21: 0.8,  # 9 PM - light\n            22: 0.6,  # 10 PM - light\n            23: 0.4   # 11 PM - very light\n        }\n        \n        # Random variation factor (±20%)\n        self.variation_factor = 0.2\n    \n    def get_traffic_multiplier(self, hour: int, add_randomness: bool = True) -> float:\n        \"\"\"Get traffic congestion multiplier for a given hour\"\"\"\n        base_multiplier = self.hourly_multipliers.get(hour % 24, 1.0)\n        \n        if add_randomness:\n            # Add random variation\n            variation = random.uniform(-self.variation_factor, self.variation_factor)\n            multiplier = base_multiplier * (1 + variation)\n            return max(0.1, multiplier)  # Minimum multiplier of 0.1\n        \n        return base_multiplier\n\n\nclass NetworkSimulator:\n    \"\"\"Main class for network simulation and traffic management\"\"\"\n    \n    def __init__(self):\n        self.graph = nx.Graph()\n        self.nodes: Dict[str, Node] = {}\n        self.links: Dict[Tuple[str, str], Link] = {}\n        self.traffic_pattern = TrafficPattern()\n        self.current_hour = 8  # Default to 8 AM\n        self.current_traffic_conditions: Dict[Tuple[str, str], float] = {}\n    \n    def create_network(self, nodes: List[Node], links: List[Link]) -> None:\n        \"\"\"\n        Build network graph from nodes and links\n        \n        Args:\n            nodes: List of Node objects representing locations\n            links: List of Link objects representing road connections\n        \"\"\"\n        # Clear existing network\n        self.graph.clear()\n        self.nodes.clear()\n        self.links.clear()\n        \n        # Add nodes to the network\n        for node in nodes:\n            self.nodes[node.id] = node\n            self.graph.add_node(node.id, \n                              name=node.name,\n                              latitude=node.latitude,\n                              longitude=node.longitude,\n                              node_type=node.node_type)\n        \n        # Add links to the network\n        for link in links:\n            # Store link information\n            link_key = (link.from_node, link.to_node)\n            reverse_key = (link.to_node, link.from_node)\n            \n            self.links[link_key] = link\n            self.links[reverse_key] = link  # Bidirectional\n            \n            # Add edge to graph with attributes\n            self.graph.add_edge(link.from_node, link.to_node,\n                              distance=link.distance,\n                              base_travel_time=link.base_travel_time,\n                              capacity=link.capacity,\n                              road_type=link.road_type)\n        \n        # Initialize traffic conditions\n        self.update_traffic_conditions(self.current_hour)\n    \n    def update_traffic_conditions(self, hour: int) -> None:\n        \"\"\"\n        Update traffic conditions for the specified hour\n        \n        Args:\n            hour: Hour of the day (0-23)\n        \"\"\"\n        self.current_hour = hour % 24\n        traffic_multiplier = self.traffic_pattern.get_traffic_multiplier(self.current_hour)\n        \n        # Update traffic conditions for all links\n        for edge in self.graph.edges():\n            node1, node2 = edge\n            link_key = (node1, node2)\n            \n            if link_key in self.links:\n                base_time = self.links[link_key].base_travel_time\n            else:\n                # Try reverse direction\n                link_key = (node2, node1)\n                base_time = self.links[link_key].base_travel_time\n            \n            # Calculate current travel time with traffic\n            current_travel_time = base_time * traffic_multiplier\n            \n            # Update graph edge weight\n            self.graph[node1][node2]['current_travel_time'] = current_travel_time\n            self.current_traffic_conditions[edge] = traffic_multiplier\n    \n    def get_travel_time(self, node1: str, node2: str) -> Optional[float]:\n        \"\"\"\n        Get current travel time between two nodes\n        \n        Args:\n            node1: Origin node ID\n            node2: Destination node ID\n            \n        Returns:\n            Current travel time in minutes, or None if no direct connection\n        \"\"\"\n        if not self.graph.has_edge(node1, node2):\n            return None\n        \n        return self.graph[node1][node2].get('current_travel_time', \n                                          self.graph[node1][node2]['base_travel_time'])\n    \n    def simulate_traffic_hour(self, hour: int) -> Dict[str, Any]:\n        \"\"\"\n        Update network for specified hour and return traffic summary\n        \n        Args:\n            hour: Hour of the day (0-23)\n            \n        Returns:\n            Dictionary containing traffic statistics for the hour\n        \"\"\"\n        self.update_traffic_conditions(hour)\n        \n        # Calculate traffic statistics\n        traffic_multipliers = list(self.current_traffic_conditions.values())\n        \n        stats = {\n            'hour': hour,\n            'average_congestion': np.mean(traffic_multipliers),\n            'max_congestion': np.max(traffic_multipliers),\n            'min_congestion': np.min(traffic_multipliers),\n            'congested_links': sum(1 for tm in traffic_multipliers if tm > 1.2),\n            'total_links': len(traffic_multipliers)\n        }\n        \n        return stats\n    \n    def get_shortest_path(self, origin: str, destination: str, weight: str = 'current_travel_time') -> Tuple[List[str], float]:\n        \"\"\"\n        Calculate shortest path between two nodes\n        \n        Args:\n            origin: Origin node ID\n            destination: Destination node ID\n            weight: Edge weight to use ('current_travel_time', 'distance', etc.)\n            \n        Returns:\n            Tuple of (path as list of node IDs, total weight)\n        \"\"\"\n        try:\n            path = nx.shortest_path(self.graph, origin, destination, weight=weight)\n            total_weight = nx.shortest_path_length(self.graph, origin, destination, weight=weight)\n            return path, total_weight\n        except nx.NetworkXNoPath:\n            return [], float('inf')\n    \n    def get_network_info(self) -> Dict[str, Any]:\n        \"\"\"Get summary information about the network\"\"\"\n        return {\n            'num_nodes': self.graph.number_of_nodes(),\n            'num_edges': self.graph.number_of_edges(),\n            'current_hour': self.current_hour,\n            'nodes': list(self.nodes.keys()),\n            'is_connected': nx.is_connected(self.graph)\n        }\n    \n    def get_traffic_summary(self) -> Dict[str, Any]:\n        \"\"\"Get current traffic condition summary\"\"\"\n        if not self.current_traffic_conditions:\n            return {}\n        \n        multipliers = list(self.current_traffic_conditions.values())\n        return {\n            'current_hour': self.current_hour,\n            'average_congestion': np.mean(multipliers),\n            'congestion_std': np.std(multipliers),\n            'highly_congested_links': sum(1 for m in multipliers if m > 1.5),\n            'light_traffic_links': sum(1 for m in multipliers if m < 0.8)\n        }\n\n\ndef create_greater_bay_area_network() -> Tuple[List[Node], List[Link]]:\n    \"\"\"\n    Create a simplified Greater Bay Area network for testing\n    Includes major cities: Hong Kong, Shenzhen, Guangzhou, Macau, Zhuhai, Dongguan, Foshan\n    \"\"\"\n    \n    # Define nodes (major cities and logistics hubs)\n    nodes = [\n        Node(\"HK\", \"Hong Kong\", 22.3193, 114.1694, \"distribution_center\"),\n        Node(\"SZ\", \"Shenzhen\", 22.5431, 114.0579, \"distribution_center\"),\n        Node(\"GZ\", \"Guangzhou\", 23.1291, 113.2644, \"distribution_center\"),\n        Node(\"MO\", \"Macau\", 22.1987, 113.5439, \"warehouse\"),\n        Node(\"ZH\", \"Zhuhai\", 22.2769, 113.5678, \"warehouse\"),\n        Node(\"DG\", \"Dongguan\", 23.0489, 113.7447, \"warehouse\"),\n        Node(\"FS\", \"Foshan\", 23.0218, 113.1219, \"warehouse\"),\n        Node(\"ZS\", \"Zhongshan\", 22.5150, 113.3927, \"customer\")\n    ]\n    \n    # Define links (major transportation routes)\n    links = [\n        # Hong Kong connections\n        Link(\"HK\", \"SZ\", 35, 45, 2000, \"highway\"),\n        \n        # Shenzhen connections  \n        Link(\"SZ\", \"GZ\", 120, 90, 1500, \"highway\"),\n        Link(\"SZ\", \"DG\", 45, 50, 1200, \"highway\"),\n        \n        # Guangzhou connections\n        Link(\"GZ\", \"FS\", 25, 35, 1800, \"highway\"),\n        Link(\"GZ\", \"DG\", 60, 65, 1000, \"highway\"),\n        \n        # Dongguan connections\n        Link(\"DG\", \"FS\", 35, 40, 800, \"arterial\"),\n        \n        # Foshan connections\n        Link(\"FS\", \"ZS\", 40, 45, 600, \"arterial\"),\n        \n        # Zhuhai/Macau connections\n        Link(\"ZH\", \"MO\", 15, 25, 500, \"arterial\"),\n        Link(\"ZH\", \"ZS\", 30, 35, 600, \"arterial\"),\n        \n        # Cross-bay connections\n        Link(\"HK\", \"ZH\", 55, 80, 800, \"highway\"),  # via bridge\n        Link(\"SZ\", \"ZS\", 70, 75, 700, \"highway\"),\n    ]\n    \n    return nodes, links\n\n\ndef run_24_hour_simulation() -> None:\n    \"\"\"Run a 24-hour traffic simulation with the Greater Bay Area network\"\"\"\n    \n    print(\"=== Greater Bay Area Network Traffic Simulation ===\\n\")\n    \n    # Create network\n    simulator = NetworkSimulator()\n    nodes, links = create_greater_bay_area_network()\n    simulator.create_network(nodes, links)\n    \n    print(f\"Network Info: {simulator.get_network_info()}\\n\")\n    \n    # Test route calculation\n    origin, destination = \"HK\", \"GZ\"\n    path, travel_time = simulator.get_shortest_path(origin, destination)\n    print(f\"Initial route from {origin} to {destination}:\")\n    print(f\"Path: {' -> '.join(path)}\")\n    print(f\"Travel time: {travel_time:.1f} minutes\\n\")\n    \n    # Simulate 24 hours\n    print(\"=== 24-Hour Traffic Simulation ===\")\n    print(\"Hour | Avg Cong | Max Cong | Congested Links | HK->GZ Time\")\n    print(\"-\" * 60)\n    \n    daily_stats = []\n    for hour in range(24):\n        stats = simulator.simulate_traffic_hour(hour)\n        path, travel_time = simulator.get_shortest_path(origin, destination)\n        \n        print(f\"{hour:2d}   | {stats['average_congestion']:8.2f} | {stats['max_congestion']:8.2f} | \"\n              f\"{stats['congested_links']:7d}/{stats['total_links']:2d}     | {travel_time:8.1f}\")\n        \n        daily_stats.append({\n            'hour': hour,\n            'avg_congestion': stats['average_congestion'],\n            'travel_time': travel_time\n        })\n    \n    # Summary statistics\n    avg_congestions = [s['avg_congestion'] for s in daily_stats]\n    travel_times = [s['travel_time'] for s in daily_stats]\n    \n    print(\"\\n=== Daily Summary ===\")\n    print(f\"Average congestion: {np.mean(avg_congestions):.2f}\")\n    print(f\"Peak congestion hour: {daily_stats[np.argmax(avg_congestions)]['hour']}:00\")\n    print(f\"Minimum travel time HK->GZ: {min(travel_times):.1f} minutes\")\n    print(f\"Maximum travel time HK->GZ: {max(travel_times):.1f} minutes\")\n    print(f\"Travel time variation: {max(travel_times) - min(travel_times):.1f} minutes\")\n\n\ndef test_network_functions() -> None:\n    \"\"\"Test individual network functions\"\"\"\n    \n    print(\"\\n=== Testing Network Functions ===\\n\")\n    \n    simulator = NetworkSimulator()\n    nodes, links = create_greater_bay_area_network()\n    \n    # Test network creation\n    print(\"1. Testing network creation...\")\n    simulator.create_network(nodes, links)\n    print(f\"✓ Created network with {len(nodes)} nodes and {len(links)} links\")\n    \n    # Test traffic condition updates\n    print(\"\\n2. Testing traffic condition updates...\")\n    for test_hour in [8, 12, 18, 2]:  # Peak morning, noon, evening, night\n        simulator.update_traffic_conditions(test_hour)\n        summary = simulator.get_traffic_summary()\n        print(f\"Hour {test_hour:2d}: Avg congestion = {summary['average_congestion']:.2f}\")\n    \n    # Test travel time queries\n    print(\"\\n3. Testing travel time queries...\")\n    test_pairs = [(\"HK\", \"SZ\"), (\"GZ\", \"FS\"), (\"ZH\", \"MO\")]\n    for node1, node2 in test_pairs:\n        travel_time = simulator.get_travel_time(node1, node2)\n        print(f\"✓ {node1} -> {node2}: {travel_time:.1f} minutes\")\n    \n    # Test shortest path calculation\n    print(\"\\n4. Testing shortest path calculation...\")\n    path, total_time = simulator.get_shortest_path(\"HK\", \"FS\")\n    print(f\"✓ Shortest path HK -> FS: {' -> '.join(path)} ({total_time:.1f} min)\")\n    \n    print(\"\\n✓ All function tests completed successfully!\")\n\n\nif __name__ == \"__main__\":\n    \"\"\"Main execution for testing and demonstration\"\"\"\n    \n    # Run function tests\n    test_network_functions()\n    \n    # Run 24-hour simulation\n    run_24_hour_simulation()\n    \n    print(\"\\n=== Network Simulation Module Test Complete ===\")",
